package romantoint

import "testing"

func TestThree(t *testing.T) {
	if got := RomanToInt("III"); got != 3 {
		t.Fatalf("got %d, want 3", got)
	}
}

func TestSubtractiveIV(t *testing.T) {
	if got := RomanToInt("IV"); got != 4 {
		t.Fatalf("got %d, want 4", got)
	}
}

func TestSubtractiveIX(t *testing.T) {
	if got := RomanToInt("IX"); got != 9 {
		t.Fatalf("got %d, want 9", got)
	}
}

func TestLVIII(t *testing.T) {
	if got := RomanToInt("LVIII"); got != 58 {
		t.Fatalf("got %d, want 58", got)
	}
}

func TestMCMXCIV(t *testing.T) {
	if got := RomanToInt("MCMXCIV"); got != 1994 {
		t.Fatalf("got %d, want 1994", got)
	}
}

func TestCurrentYear(t *testing.T) {
	if got := RomanToInt("MMXXIV"); got != 2024 {
		t.Fatalf("got %d, want 2024", got)
	}
}

func TestSingleD(t *testing.T) {
	if got := RomanToInt("D"); got != 500 {
		t.Fatalf("got %d, want 500", got)
	}
}

func TestMax(t *testing.T) {
	if got := RomanToInt("MMMCMXCIX"); got != 3999 {
		t.Fatalf("got %d, want 3999", got)
	}
}
